// Online co-op (experimental): ?host opens a room and streams this screen (game plus HUD) to one friend over WebRTC with Trystero
// (Nostr relays for signalling, no server of ours); ?join=CODE plays that stream full-screen and sends the friend's keys or gamepad
// back as player two, who drives squad bot 1 exactly like local player two.
const NET_JOIN65=(params.get('join')||'').toUpperCase().replace(/[^A-Z]/g,'').slice(0,6),NET_HOST65=params.has('host')&&!NET_JOIN65;
const net65={room:null,code:'',peers:0,remote:{x:0,y:0,at:-9},status:''};
async function netRoom65(code){const {joinRoom}=await import('https://cdn.jsdelivr.net/npm/trystero@0.25.4/+esm');return joinRoom({appId:'tront-tinyzombies-v1'},'tz-'+code);}
async function hostOnline65(){try{const code=Array.from({length:4},()=>'ABCDEFGHJKLMNPQRSTUVWXYZ'[Math.floor(Math.random()*24)]).join('');net65.code=code;net65.status='connecting';
  const room=await netRoom65(code);net65.room=room;net65.status='waiting for player 2';
  const comp=document.createElement('canvas');comp.width=960;comp.height=540;const cx=comp.getContext('2d');
  const blit=()=>{try{cx.drawImage(canvas,0,0,comp.width,comp.height);const h=document.getElementById('hud2d');if(h)cx.drawImage(h,0,0,comp.width,comp.height);}catch(e){}requestAnimationFrame(blit);};blit();
  const stream=comp.captureStream(30);const input=room.makeAction('p2in');// Trystero 0.25: action objects and property callbacks
  input.onMessage=d=>{net65.remote={x:clamp9(+d.x||0,-1,1),y:clamp9(+d.y||0,-1,1),at:time};};
  room.onPeerJoin=id=>{net65.peers++;net65.status='player 2 connected';room.addStream(stream,{target:id});announce65('Player two is online!',true);};
  room.onPeerLeave=()=>{net65.peers=Math.max(0,net65.peers-1);if(!net65.peers)net65.status='waiting for player 2';};
 }catch(e){net65.status='offline: '+String(e.message||e).slice(0,60);}}
function joinOnline65(code){boot.hidden=true;canvas.style.display='none';
 const v=document.createElement('video');v.autoplay=true;v.playsInline=true;v.muted=true;Object.assign(v.style,{position:'fixed',inset:'0',width:'100vw',height:'100vh',objectFit:'contain',background:'#000'});document.body.appendChild(v);
 const label=document.createElement('div');Object.assign(label.style,{position:'fixed',left:'16px',bottom:'14px',color:'#f6d43a',font:'600 15px Rubik,system-ui,sans-serif',textShadow:'0 2px 3px #000'});label.textContent='Joining room '+code+'...';document.body.appendChild(label);
 netRoom65(code).then(room=>{label.textContent='Room '+code+': waiting for the host...';
  room.onPeerStream=s=>{v.srcObject=s;v.play().catch(()=>{});label.textContent='You are PLAYER 2 (room '+code+'): WASD, arrows or a gamepad';};
  const input=room.makeAction('p2in');const held=new Set();addEventListener('keydown',e=>held.add(e.code));addEventListener('keyup',e=>held.delete(e.code));addEventListener('blur',()=>held.clear());
  const k=c=>held.has(c)?1:0;setInterval(()=>{let x=Math.max(k('KeyD'),k('ArrowRight'),k('KeyL'))-Math.max(k('KeyA'),k('ArrowLeft'),k('KeyJ')),y=Math.max(k('KeyW'),k('ArrowUp'),k('KeyI'))-Math.max(k('KeyS'),k('ArrowDown'),k('KeyK'));
   try{const g=[...(navigator.getGamepads?.()||[])].find(p=>p&&p.connected);if(g&&Math.hypot(g.axes[0]||0,g.axes[1]||0)>.25){x=g.axes[0];y=-g.axes[1];}}catch(e){}input.send({x,y});},50);
 }).catch(e=>{label.textContent='Could not join room '+code+': '+(e.message||e);});}
